\label{prop:D_second_derivative}
	The second derivative of \(D_{\omega}(s)\) at \(s=1\) is given by
	\begin{equation}\label{eq:D_second_derivative}
		D_{\omega}''(1)=8\,C_2\ln 2
		\approx
		3.660714432\ldots
	\end{equation}

\label{prop:error_analysis}
	For every \(K\ge 2\),
	\begin{equation}\label{eq:error_exact}
		\mathcal{F}_{\mathrm{Tri}}(K)-\mathcal{F}(K)
		=
		\frac{\Lambda_K}{K}+R_K,
	\end{equation}
	where the remainder satisfies
	\begin{equation}\label{eq:error_bound}
		|R_K|
		\le
		C\,\frac{e^{-c\sqrt{\log K}}\log K}{K}
	\end{equation}
	for absolute constants \(C,c>0\).  In particular,
	\[
	\bigl|\mathcal{F}_{\mathrm{Tri}}(K)-\mathcal{F}(K)\bigr|
	=
	O\!\left(\frac{e^{-c\sqrt{\log K}}\log K}{K}\right),
	\]
	which is \(o(K^{-\alpha})\) for every \(0<\alpha\le1\), but not
	for \(\alpha>1\).

\label{lem:h_not_cyclotomic}
	The function \(h(z)=(1-2z)/(1-z)\) is \emph{not} a product of
	cyclotomic polynomials.
